{
  "pictures": [
    {
      "index": 3,
      "question": "Which of these is a proper fraction?",
      "options": [
        "$\\frac{2}{5}$",
        "$\\frac{7}{4}$",
        "$\\frac{5}{3}$"
      ],
      "correct_index": 0,
      "explanation": "A proper fraction is a fraction where the numerator (the top number) is smaller than the denominator (the bottom number).",
      "selected_because": "The teacher explained proper fractions with examples like 2/5.",
      "distractor_misconceptions": {
        "1": "Confuses proper and improper fractions, thinking a larger numerator is proper.",
        "2": "Confuses proper and improper fractions, thinking a larger numerator is proper."
      },
      "option_feedback": {
        "correct": "You are right! A proper fraction has a numerator that is smaller than its denominator, like $\\frac{2}{5}$.",
        "wrong": {
          "1": "This is an improper fraction because the numerator is larger than the denominator. Remember, in a proper fraction, the top number is smaller than the bottom number.",
          "2": "This is an improper fraction because the numerator is larger than the denominator. Remember, in a proper fraction, the top number is smaller than the bottom number."
        }
      },
      "figure": {
        "type": "fraction_bar",
        "bars": [
          {
            "parts": 5,
            "shaded": 2,
            "label": "$\\frac{2}{5}$"
          },
          {
            "parts": 4,
            "shaded": 7,
            "label": "$\\frac{7}{4}$"
          },
          {
            "parts": 3,
            "shaded": 5,
            "label": "$\\frac{5}{3}$"
          }
        ]
      },
      "figure_role": "model",
      "slo_id": "S4",
      "level": "understand"
    },
    {
      "index": 6,
      "replace": true,
      "level": "apply",
      "question": "What mixed number does the picture show?",
      "options": [
        "$1\\frac{3}{4}$",
        "$2\\frac{1}{4}$",
        "$1\\frac{1}{2}$"
      ],
      "correct_index": 0,
      "explanation": "The picture shows one whole bar completely shaded and three out of four parts shaded in the second bar, which represents $1\\frac{3}{4}$.",
      "selected_because": "The teacher demonstrated converting improper fractions to mixed numbers using visual models.",
      "distractor_misconceptions": {
        "1": "Counts the total shaded parts and total parts incorrectly.",
        "2": "Misinterprets the shaded parts in the second bar."
      },
      "option_feedback": {
        "correct": "Excellent! The picture shows one whole bar and three-quarters of another bar, which is $1\\frac{3}{4}$.",
        "wrong": {
          "1": "Look closely at the second bar. How many parts are shaded out of the total parts? The first bar is one whole.",
          "2": "The second bar has 4 parts in total, and 3 are shaded, not 2. Remember to count all the parts in the second bar."
        }
      },
      "figure": {
        "type": "fraction_bar",
        "bars": [
          {
            "parts": 4,
            "shaded": 4
          },
          {
            "parts": 4,
            "shaded": 3
          }
        ]
      },
      "figure_role": "read_off",
      "slo_id": "S6"
    }
  ]
}
